<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/ShopAccessFixture.php';
use DigiForge\Database\Tables;
use DigiForge\Listings\EtsyOperationRepository;
use DigiForge\Portal\HistoricalFailurePanel;

/** Actual local ledger transitions and operator HTML; synthetic evidence, never external calls. */
final class PortalHistoricalFailureAcceptanceTest extends WP_UnitTestCase
{
 private int $httpCalls=0;
 private mixed $httpGuard;
 protected function setUp():void {
  parent::setUp();DigiForge\Core\Activator::activate();wp_salt('nonce');DigiForge\Core\Settings::protectProduction();ShopAccessFixture::reset();wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));ShopAccessFixture::authorizeActor(get_current_user_id(),['digital','personalized_pod','standard_pod','jewelry'],DigiForge\Core\Capabilities::ALL);
  $this->httpGuard=function(){++$this->httpCalls;return new WP_Error('offline_historical_failure','HTTP forbidden.');};add_filter('pre_http_request',$this->httpGuard,1,3);
 }
 protected function tearDown():void {remove_filter('pre_http_request',$this->httpGuard,1);self::assertSame(0,$this->httpCalls);self::assertTrue(DigiForge\Core\Settings::get('stop_all',true));self::assertTrue(DigiForge\Core\Settings::safety_locked());self::assertFalse(DigiForge\Core\Settings::get('automation_armed',false));parent::tearDown();}
 private function failed(string $shop,string $terminal='CONFIRMED_FAILURE'):array {
  global $wpdb;$now=current_time('mysql',true);$hash=hash('sha256',wp_generate_uuid4());
  self::assertSame(1,$wpdb->insert(Tables::listings(),['product_version_id'=>1,'environment'=>'sandbox','shop_reference'=>$shop,'title'=>'Offline historical operation','state'=>'APPROVED','approved_by'=>get_current_user_id(),'approved_at'=>$now,'created_at'=>$now,'updated_at'=>$now]));$listing=(int)$wpdb->insert_id;
  self::assertSame(1,$wpdb->insert(Tables::etsy_draft_packages(),['listing_id'=>$listing,'package_version'=>wp_generate_uuid4(),'canonical_payload'=>'{}','payload_hash'=>$hash,'readiness'=>'{}','readiness_hash'=>$hash,'approved_by'=>get_current_user_id(),'approved_at'=>$now,'created_at'=>$now]));$package=(int)$wpdb->insert_id;
  self::assertSame(1,$wpdb->insert(Tables::etsy_intents(),['listing_id'=>$listing,'draft_package_id'=>$package,'environment'=>'sandbox','intent_type'=>'PREPARE_DRAFT','state'=>'APPROVED_INTENT','created_at'=>$now,'updated_at'=>$now]));$intent=(int)$wpdb->insert_id;
  $repo=new EtsyOperationRepository();$operation=$repo->createFromPayload(['shop_reference'=>$shop,'intent_id'=>$intent,'draft_package_id'=>$package,'operation_type'=>'CREATE_DRAFT','idempotency_key'=>'history-'.wp_generate_uuid4(),'authorization_hash'=>$hash,'evidence_hash'=>$hash],['private_body'=>'must-not-render','title'=>'Offline fixture']);self::assertNotWPError($operation);self::assertNotWPError($repo->transition((int)$operation['id'],'SENT'));$final=$repo->transition((int)$operation['id'],$terminal,$terminal==='CONFIRMED_SUCCESS'?'private-external-reference':'');self::assertNotWPError($final);return $final;
 }
 private function render(string $shop):string {$before=$_GET;$writes=[];$watch=static function(string $sql)use(&$writes):string{if(preg_match('/^\s*(INSERT|UPDATE|DELETE|REPLACE|ALTER|DROP|CREATE|TRUNCATE)\b/i',$sql))$writes[]=$sql;return $sql;};add_filter('query',$watch);try{$_GET=['df_view'=>'audit','df_shop'=>$shop];$html=(new DigiForge\Portal\Portal())->render();}finally{$_GET=$before;remove_filter('query',$watch);}self::assertSame([],$writes);return $html;}
 private function panel(string $html):DOMElement {$doc=new DOMDocument();@$doc->loadHTML($html,LIBXML_NONET);$nodes=(new DOMXPath($doc))->query('//section[h2[text()="Historical failed Etsy operations"]]');self::assertSame(1,$nodes->length);return $nodes->item(0);}
 public function testTerminalFailureHistoryIsScopedBeforeWindowAndImmutableWithNoRetryAuthority():void {
  $own=$this->failed('digital');$foreign=$this->failed('jewelry');$success=$this->failed('digital','CONFIRMED_SUCCESS');$unknown=$this->failed('digital','UNKNOWN');$unmapped=$this->failed('unassigned_shop');$snapshot=HistoricalFailurePanel::snapshot('digital',1);self::assertSame('AVAILABLE',$snapshot['query_state']);self::assertCount(1,$snapshot['items']);self::assertSame((int)$own['id'],(int)$snapshot['items'][0]['id']);self::assertFalse($snapshot['retry_permitted']);self::assertFalse($snapshot['external_execution_authorized']);
  $html=$this->render('digital');$this->capture('digital',$html);$panel=$this->panel($html);$xpath=new DOMXPath($panel->ownerDocument);$rows=$xpath->query('.//tbody/tr',$panel);self::assertSame(1,$rows->length);$cells=$rows->item(0)->getElementsByTagName('td');foreach([0=>(string)$own['id'],1=>'digital',2=>'CREATE_DRAFT',3=>'CONFIRMED_FAILURE',4=>$own['request_fingerprint'],5=>$own['evidence_hash'],7=>'NO']as $i=>$value)self::assertSame($value,$cells->item($i)->textContent);self::assertSame(0,$xpath->query('.//form|.//button',$panel)->length);self::assertStringNotContainsString('must-not-render',$panel->textContent);self::assertStringNotContainsString('private-external-reference',$panel->textContent);
  $repo=new EtsyOperationRepository();self::assertWPError($repo->transition((int)$own['id'],'SENT'));self::assertSame($own,$repo->find((int)$own['id']));self::assertSame($foreign,$repo->find((int)$foreign['id']));self::assertSame($success,$repo->find((int)$success['id']));self::assertSame($unknown,$repo->find((int)$unknown['id']));$global=HistoricalFailurePanel::snapshot('all',1);self::assertSame('AVAILABLE',$global['query_state']);self::assertTrue($global['truncated']);self::assertSame((int)$foreign['id'],(int)$global['items'][0]['id']);
 }
 public function testMissingReadAndMalformedRecordedHashesCannotMasqueradeAsEmptyHistory():void {
  $own=$this->failed('digital');global $wpdb;$table=$wpdb->prefix.'digiforge_etsy_operations';$fault=static fn(string $sql):string=>str_starts_with($sql,'SELECT history_operation.id')?str_replace($table,$table.'_missing_history_fixture',$sql):$sql;$prior=$wpdb->suppress_errors(true);add_filter('query',$fault);try{$panel=$this->panel($this->render('digital'));self::assertStringContainsString('Historical failure evidence unavailable',$panel->textContent);self::assertStringNotContainsString('No terminal failures',$panel->textContent);}finally{remove_filter('query',$fault);$wpdb->suppress_errors($prior);}
  self::assertSame(1,$wpdb->update($table,['evidence_hash'=>'invalid'],['id'=>$own['id']]));self::assertSame('UNAVAILABLE',HistoricalFailurePanel::snapshot('digital')['query_state']);$panel=$this->panel($this->render('digital'));self::assertStringContainsString('No empty or cleared history is inferred',$panel->textContent);
 }
 public function testUnassignedActorPartialGlobalAssignmentAndUnknownShopFailClosed():void {
  self::assertSame('UNAVAILABLE',HistoricalFailurePanel::snapshot('unknown')['query_state']);$actor=self::factory()->user->create(['role'=>'administrator']);wp_set_current_user($actor);self::assertSame('UNAVAILABLE',HistoricalFailurePanel::snapshot('digital')['query_state']);ShopAccessFixture::authorizeActor($actor,['digital'],['manage_digiforge']);$this->failed('digital');self::assertSame('AVAILABLE',HistoricalFailurePanel::snapshot('digital')['query_state']);self::assertSame('UNAVAILABLE',HistoricalFailurePanel::snapshot('jewelry')['query_state']);self::assertSame('UNAVAILABLE',HistoricalFailurePanel::snapshot('all')['query_state']);
 }
 private function providerFailure(string $shop,string $code='fixture_rejected'):array {
  global $wpdb;$order=(new DigiForge\Orders\Repository())->createOrder(['shop_reference'=>$shop,'environment'=>'sandbox']);self::assertNotWPError($order);$now=current_time('mysql',true);$packageHash=hash('sha256',wp_generate_uuid4());$authHash=hash('sha256',wp_generate_uuid4());$nonce='history_'.str_replace('-','',wp_generate_uuid4());$actor=get_current_user_id();
  self::assertSame(1,$wpdb->insert(Tables::pod_authorization_packages(),['order_id'=>$order['id'],'render_evidence_id'=>1,'provider_mapping_id'=>1,'ownership_mapping_id'=>1,'readiness_hash'=>hash('sha256','synthetic-readiness'),'package_hash'=>$packageHash,'state'=>'APPROVED_PACKAGE','approved_by'=>$actor,'approved_at'=>$now,'external_execution_authorized'=>0,'external_execution_performed'=>0,'created_at'=>$now]));$package=(int)$wpdb->insert_id;
  // Synthetic consumed permit provenance, not a production permit or a provider attempt.
  self::assertTrue(DigiForge\POD\ExecutionNonceLedger::consume($nonce,$authHash,$actor));self::assertSame(1,$wpdb->insert(Tables::pod_authorization_bindings(),['package_id'=>$package,'package_hash'=>$packageHash,'authorization_hash'=>$authHash,'nonce_hash'=>hash('sha256',$nonce),'bound_by'=>$actor,'bound_at'=>$now]));
  $authorization=['authorization_hash'=>$authHash,'authorization'=>['nonce'=>$nonce]];$permit=['state'=>'ADAPTER_CALL_PERMITTED','nonce_consumed'=>true,'external_execution_performed'=>false,'action'=>'PRINTIFY_ORDER_CREATE','authorization_hash'=>$authHash,'evidence_hash'=>$packageHash];
  $record=DigiForge\POD\ExecutionFailureRecord::record($authorization,$permit,['status'=>'FAILED','failure_category'=>'adapter_error','failure_code'=>$code],$actor,time());self::assertNotWPError($record);$saved=DigiForge\POD\ExecutionFailureRepository::save($record);self::assertNotWPError($saved);return compact('saved','record','order','package','authorization','permit','nonce');
 }
 private function providerPanel(string $html):DOMElement {$doc=new DOMDocument();@$doc->loadHTML($html,LIBXML_NONET);$nodes=(new DOMXPath($doc))->query('//section[h2[text()="Historical failed POD executions"]]');self::assertSame(1,$nodes->length);return $nodes->item(0);}
 private function capture(string $shop,string $html):void {$directory=getenv('DF_PORTAL_FIXTURE_DIR');if(is_string($directory)&&$directory!==''&&is_dir($directory))self::assertSame(strlen($html),file_put_contents($directory.'/portal-audit--'.$shop.'.html',$html));}
 public function testProviderFailureHistoryVerifiesActualRecordHashAndExactShopPackageAncestryWithoutRetry():void {
  $own=$this->providerFailure('personalized_pod');$foreign=$this->providerFailure('jewelry');$unmapped=$this->providerFailure('unassigned_shop');$snapshot=HistoricalFailurePanel::providerSnapshot('personalized_pod',1);self::assertSame('AVAILABLE',$snapshot['query_state']);self::assertCount(1,$snapshot['items']);self::assertSame((int)$own['saved']['id'],$snapshot['items'][0]['id']);self::assertSame($own['saved']['failure_hash'],$snapshot['items'][0]['failure_hash']);
  global $wpdb;$before=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::pod_execution_failures().' WHERE id=%d',$own['saved']['id']),ARRAY_A);$html=$this->render('personalized_pod');$this->capture('personalized_pod',$html);$panel=$this->providerPanel($html);$xpath=new DOMXPath($panel->ownerDocument);$rows=$xpath->query('.//tbody/tr',$panel);self::assertSame(1,$rows->length);$cells=$rows->item(0)->getElementsByTagName('td');foreach([0=>(string)$own['saved']['id'],1=>'personalized_pod',2=>(string)$own['order']['id'],3=>(string)$own['package'],4=>'PRINTIFY_ORDER_CREATE',5=>'adapter_error',6=>'fixture_rejected',7=>$own['saved']['failure_hash'],8=>$own['saved']['evidence_hash'],10=>'NO']as $i=>$value)self::assertSame($value,$cells->item($i)->textContent);self::assertSame(0,$xpath->query('.//form|.//button',$panel)->length);foreach([$own['nonce'],$own['saved']['authorization_hash'],$own['saved']['nonce_hash'],$foreign['saved']['failure_hash']]as $private)self::assertStringNotContainsString($private,$panel->textContent);
  self::assertNotWPError(DigiForge\POD\ExecutionFailureRepository::save($own['record']));$changed=DigiForge\POD\ExecutionFailureRecord::record($own['authorization'],$own['permit'],['status'=>'FAILED','failure_category'=>'adapter_error','failure_code'=>'different_fixture_error'],get_current_user_id(),$own['record']['failure']['recorded_at']);self::assertNotWPError($changed);self::assertWPError(DigiForge\POD\ExecutionFailureRepository::save($changed));self::assertSame($before,$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::pod_execution_failures().' WHERE id=%d',$own['saved']['id']),ARRAY_A));$global=HistoricalFailurePanel::providerSnapshot('all',1);self::assertSame('AVAILABLE',$global['query_state']);self::assertTrue($global['truncated']);self::assertSame((int)$foreign['saved']['id'],$global['items'][0]['id']);self::assertFalse($global['retry_permitted']);
 }
 public function testProviderHistoryRejectsHashTamperingAndExactPackageBindingDrift():void {
  $own=$this->providerFailure('digital');global $wpdb;self::assertSame(1,$wpdb->update(Tables::pod_execution_failures(),['failure_code'=>'altered'],['id'=>$own['saved']['id']]));self::assertSame('UNAVAILABLE',HistoricalFailurePanel::providerSnapshot('digital')['query_state']);self::assertStringContainsString('POD historical failure evidence unavailable or inconsistent',$this->providerPanel($this->render('digital'))->textContent);self::assertSame(1,$wpdb->update(Tables::pod_execution_failures(),['failure_code'=>$own['saved']['failure_code']],['id'=>$own['saved']['id']]));
  self::assertSame(1,$wpdb->update(Tables::pod_authorization_bindings(),['package_hash'=>hash('sha256','wrong-history-package')],['authorization_hash'=>$own['saved']['authorization_hash']]));self::assertSame('UNAVAILABLE',HistoricalFailurePanel::providerSnapshot('digital')['query_state']);self::assertSame(1,$wpdb->update(Tables::pod_authorization_bindings(),['package_hash'=>$own['saved']['evidence_hash']],['authorization_hash'=>$own['saved']['authorization_hash']]));self::assertSame('AVAILABLE',HistoricalFailurePanel::providerSnapshot('digital')['query_state']);
 }
 public function testProviderHistoryReadFailureAndMissingAssignmentNeverBecomeEmptyOrAuthorized():void {
  $own=$this->providerFailure('digital');global $wpdb;$table=Tables::pod_execution_failures();$fault=static fn(string $sql):string=>str_starts_with($sql,'SELECT history_failure.*')?str_replace($table,$table.'_missing_history_fixture',$sql):$sql;$prior=$wpdb->suppress_errors(true);add_filter('query',$fault);try{$panel=$this->providerPanel($this->render('digital'));self::assertStringContainsString('No empty or cleared history is inferred',$panel->textContent);self::assertStringNotContainsString('No bound POD terminal failures',$panel->textContent);}finally{remove_filter('query',$fault);$wpdb->suppress_errors($prior);}
  wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));self::assertSame('UNAVAILABLE',HistoricalFailurePanel::providerSnapshot('digital')['query_state']);self::assertSame('UNAVAILABLE',HistoricalFailurePanel::providerSnapshot('all')['query_state']);self::assertSame('UNAVAILABLE',HistoricalFailurePanel::providerSnapshot('unknown')['query_state']);
 }

 public function testProviderHistoryAcceptsThePersistedHundredCharacterFailureCodeBoundary():void {
  $own=$this->providerFailure('digital',str_repeat('x',100));$view=HistoricalFailurePanel::providerSnapshot('digital');self::assertSame('AVAILABLE',$view['query_state']);self::assertContains(str_repeat('x',100),array_column($view['items'],'failure_code'));self::assertContains($own['saved']['failure_hash'],array_column($view['items'],'failure_hash'));
 }
}
